/* Shared browser-demo coordination for the three isolated role modules. */
const SH_STATE_KEY='shp-workspace-v11';
function readWorkspace(){try{const v=JSON.parse(localStorage.getItem(SH_STATE_KEY));return v&&typeof v==='object'&&!Array.isArray(v)?v:{};}catch{return {};}}
const workspace=readWorkspace();
for(const key of ['quotes','leadNotes','inventory','documents','agreements','notifications','inspections','variations','tenderScopes','tenderOptions','contractorQuotes','claims','tasks','businessProfiles','rowDrafts','subscriptions','suppliers','upgrades','shipments','freightIncidents','deliveryReceipts','upgradeSelections','bomDocuments','tenderPackages','tradeBusinesses','tenderShortlists','inventoryChecks'])if(!Array.isArray(workspace[key]))workspace[key]=[];
workspace.preferences||={};
workspace.confirmedProjects||=[];
for(const p of workspace.confirmedProjects)if(!projects.some(x=>x.id===p.id))projects.push(p);
if(!workspace.feeTrialApproved){workspace.fees={contractorMonthly:99,customerTender:399,gstRate:15};workspace.feeTrialApproved='User-selected trial: 15 October 2026';}
workspace.fees||={contractorMonthly:99,customerTender:399,gstRate:15};
const newId=()=>crypto.randomUUID();
function saveWorkspace(){try{localStorage.setItem(SH_STATE_KEY,JSON.stringify(workspace));localStorage.setItem('sh-demo-leads',JSON.stringify(leads));return true;}catch{toast('Browser storage is unavailable or full. This change has not been saved.');return false;}}
function notifyProject(event){workspace.notifications.unshift({...event,id:newId(),createdAt:new Date().toISOString(),readBy:[]});saveWorkspace();}
function permittedProjects(){return role==='staff'?projects:role==='customer'?projects.filter((p,i)=>i===0||p.isDemo):projects.filter((p,i)=>i===2||(i===0&&!!award)||p.isDemo);}
function currentProject(){const allowed=permittedProjects();const key=role==='staff'?'staffProjectId':role==='contractor'?'contractorProjectId':'customerProjectId';const p=allowed.find(p=>p.id===workspace[key])||allowed[0];workspace[key]=p.id;return p;}
function context(){const p=currentProject();if(role==='staff'&&workspace.tradeTargetProjectId!==p.id){workspace.tradeTargetProjectId=p.id;workspace.tradeTargetRegion=p.place;}return {role,projectId:p.id,project:p,projects:permittedProjects(),leads,money,escape,toast,navigate:go,store:workspace,save:saveWorkspace,notify:notifyProject,files:window.SHFiles.forProject(p.id)};}
function visibleNotifications(){const ids=permittedProjects().map(p=>p.id);return workspace.notifications.filter(n=>(!n.roles||n.roles.includes(role))&&(!n.projectId||ids.includes(n.projectId)));}
function unreadNotifications(){return visibleNotifications().filter(n=>!n.readBy?.includes(role)).length;}
function activeHolds(projectId){return workspace.inspections.filter(x=>x.projectId===projectId&&x.status!=='Recorded pass');}
function holdNotice(projectId){const holds=activeHolds(projectId).sort((a,b)=>String(a.due).localeCompare(String(b.due)));return holds.length?`<div class="hold-banner"><strong>${holds.length} inspection hold point${holds.length===1?' requires':'s require'} attention</strong><span>${escape(holds[0].name)} before ${escape(holds[0].nextStage)} · planned ${escape(holds[0].due)}. Confirm the actual consent requirement and booking before progressing.</span> <button class="link" data-go="${role==='customer'?'Inspections':'Project coordination'}">Review hold points →</button></div>`:'';}
function baseMenuGroups(){if(role==='staff')return [['Workspace',['Overview','Sales & CRM','Lead pricing','Sales & marketing']],['Project delivery',['Projects','Kitset inventory','Approved documents','Supply agreements','Project coordination']],['Marketplace & team',['Tender marketplace','Marketplace fees','Notifications','Development roadmap']]];if(role==='customer')return [['Your home',['Overview','Projects','Inspections','Variations','Project documents','Kitset inventory']],['Tender your build',['Tender scope','Tender marketplace','Notifications','Development roadmap']]];return [['Your business',['Overview','Business & team','TMP membership','Tender marketplace']],['Project delivery',['Projects','Scope package','Contractor pricing','Task progress','Claims & invoices','Project coordination','Record of Work','Notifications','Development roadmap']]];}
function baseModuleFor(p){const m=role==='staff'?window.SHStaff:role==='customer'?window.SHCustomer:window.SHContractor;return m.pages.includes(p)?m:null;}
function notificationPage(){return heading('Every decision has a next step.','Project activity and reminders visible to this role in the browser preview.')+`<section class="card"><div class="card-top"><h2>Activity inbox</h2><button class="secondary" id="markAllRead">Mark all read</button></div>${visibleNotifications().map(n=>`<article class="notification ${n.readBy?.includes(role)?'is-read':''}"><span class="dot"></span><div class="notification-body"><h3>${escape(n.title)}</h3><p>${escape(n.message)}</p><span class="small">${escape(n.projectId||'Business')} · ${escape(n.createdAt)} · ${escape(n.kind||'Update')}</span></div><button class="link" data-read="${escape(n.id)}">${n.readBy?.includes(role)?'Read':'Mark read'}</button></article>`).join('')||'<div class="empty"><h3>You’re up to date.</h3><p>Documents, inspection hold points, scope revisions and variations create project notifications here.</p></div>'}</section><section class="card workspace-activity"><h2>How notifications work in this release</h2><p>Events appear immediately in this browser’s role previews. Production delivery will use an in-app audit trail, email for required decisions, and opt-in SMS for urgent inspection or site blockers, with acknowledgements and overdue escalation.</p><p class="small">No emails, SMS or browser push messages are sent. All recipients will require verified project membership.</p></section>`;}
function coordinationPage(){const c=context(),v=workspace.variations.filter(x=>x.projectId===c.projectId);return heading('Changes agreed. Work coordinated.','Review hold points and assess customer variations before work proceeds.')+`<section class="card"><h2>Consent inspection hold points</h2><p>Track actual consent requirements and verify council evidence. A local result does not grant building approval.</p>${workspace.inspections.filter(x=>x.projectId===c.projectId).map(x=>`<div class="activity"><div><h3>${escape(x.name)}</h3><p>Before ${escape(x.nextStage)} · ${escape(x.due)} · ${escape(x.reference)}</p><span class="tag ${x.status==='Recorded pass'?'':'amber'}">${escape(x.status)}</span><p class="small">${escape(x.evidence||'Evidence not yet recorded')}</p></div></div>`).join('')||'<p>No hold points mapped yet. The customer can add requirements from their actual consent schedule.</p>'}</section><section class="card workspace-activity"><h2>Variation assessment</h2><p>Customer request → team assessment → customer approval → approved work. Record any necessary consent amendment and contract approval separately.</p>${v.map(x=>`<article class="customer-item"><h3>${escape(x.title)}</h3><span class="tag amber">${escape(x.status)}</span><p>${escape(x.description)}</p><p>Cost impact: ${escape(x.costImpact)} · Time impact: ${escape(x.timeImpact)}</p>${x.status!=='approved work'?`<form data-assess="${escape(x.id)}" class="shared-forms"><div><label>Assessment, scope and consent implications<textarea name="assessment" required maxlength="5000">${escape(x.assessment||'')}</textarea></label><label>Assessed cost impact<input name="costImpact" value="${escape(x.costImpact)}" required maxlength="200"></label><label>Assessed programme impact<input name="timeImpact" value="${escape(x.timeImpact)}" required maxlength="200"></label></div><div><label>Next review step<select name="status"><option value="assessment">Keep in assessment</option><option value="customer approval">Request customer approval</option></select></label><label><input type="checkbox" name="reviewed" required style="width:auto"> I reviewed the requested scope, cost and time impacts in this demo.</label><button class="primary">Save assessment & notify parties</button><p class="small">This records a demonstration workflow only. No real approval, message or work instruction is sent.</p></div></form>`:`<p><strong>Customer decision recorded.</strong> Coordinate the agreed work and any consent amendment before starting.</p>`}<div class="variation-history">${(x.history||[]).map(h=>`${escape(h.at)} · ${escape(h.by)} · ${escape(h.status)}`).join('<br>')}</div></article>`).join('')||'<div class="empty">No customer variation requests for this project.</div>'}</section>`;}
function bindShared(){document.querySelectorAll('[data-read]').forEach(b=>b.onclick=()=>{const n=workspace.notifications.find(x=>x.id===b.dataset.read);if(n){n.readBy||=[];if(!n.readBy.includes(role))n.readBy.push(role);saveWorkspace();render();}});const all=$('#markAllRead');if(all)all.onclick=()=>{visibleNotifications().forEach(n=>{n.readBy||=[];if(!n.readBy.includes(role))n.readBy.push(role);});saveWorkspace();render();};document.querySelectorAll('[data-assess]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const v=workspace.variations.find(x=>x.id===f.dataset.assess&&x.projectId===context().projectId);if(!v||v.status==='approved work')return;const d=Object.fromEntries(new FormData(f));Object.assign(v,{assessment:d.assessment,costImpact:d.costImpact,timeImpact:d.timeImpact,status:d.status,assessedBy:role,assessedAt:new Date().toISOString()});v.history||=[];v.history.push({at:v.assessedAt,by:role,status:v.status});notifyProject({title:'Variation assessment updated',message:`${v.title}: ${v.status}. Cost: ${v.costImpact}. Time: ${v.timeImpact}.`,roles:['staff','customer','contractor'],projectId:v.projectId,kind:'variation'});saveWorkspace();render();toast('Assessment saved; project roles notified in this browser');});}
function staffFollowthrough(){if(role!=='staff')return '';const i=workspace.staffLead??0,l=leads[i],q=workspace.quotes.find(x=>x.leadIndex===i),linked=workspace.confirmedProjects.find(x=>x.leadIndex===i);if(page==='Lead pricing'&&l)return `<section class="card"><h2>From accepted quote to confirmed project</h2>${linked?`<p>${escape(linked.name)} · ${escape(linked.id)} is linked to this lead.</p><button class="secondary" id="openConverted">Open confirmed project</button>`:q&&['Contract ready','Confirmed'].includes(q.stage)?`<form id="convertLead" class="shared-forms"><div><label>Project name<input name="name" value="${escape(l.name)} — kitset project" required maxlength="120"></label><label>Kitset model / specification<input name="model" required maxlength="120" placeholder="Confirm from accepted quote"></label></div><div><label>Next contracted milestone date<input name="date" type="date" required></label><label><input name="confirmed" type="checkbox" required style="width:auto"> Record a demo project from this contract-ready lead. This does not sign an agreement.</label><button class="primary">Create confirmed demo project</button></div></form>`:'<p>Save pricing at “Contract ready” or “Confirmed” to prepare the linked project. Complete legal review and real agreement execution outside this concept.</p>'}</section>`;if(page==='Kitset inventory')return `<section class="card"><h2>Ordering handover</h2><p>Export the itemized schedule for supplier reconciliation. Zero quantities and unspecified components must be resolved before any purchase order.</p><button class="secondary" id="exportInventory">Download ordering CSV</button></section>`;if(page==='Supply agreements')return `<section class="card"><h2>Reviewable supply particulars</h2><p>Export saved particulars with the current inventory references for professional review. The export is marked unreviewed and carries no signature or binding acceptance.</p><button class="secondary" id="exportAgreement">Download draft particulars</button></section>`;return '';}
function downloadText(name,text,type='text/plain'){const url=URL.createObjectURL(new Blob([text],{type}));const a=document.createElement('a');a.href=url;a.download=name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}
function bindFollowthrough(){const l=$('#convertLead');if(l)l.onsubmit=e=>{e.preventDefault();const i=workspace.staffLead??0;if(workspace.confirmedProjects.some(x=>x.leadIndex===i))return;const f=Object.fromEntries(new FormData(l));const p={id:`SH-DEMO-${Date.now()}`,name:f.name,client:leads[i].name,place:leads[i].region,model:f.model,stage:'Contract confirmed',progress:5,date:f.date,leadIndex:i};workspace.confirmedProjects.push(p);projects.push(p);leads[i].stage='Confirmed';workspace.staffProjectId=p.id;notifyProject({title:'Confirmed demo project created',message:`${p.name} linked to ${leads[i].name}. Verify actual contract and supply scope before proceeding.`,roles:['staff'],projectId:p.id,kind:'contract'});saveWorkspace();go('Project detail');};const open=$('#openConverted');if(open)open.onclick=()=>{workspace.staffProjectId=workspace.confirmedProjects.find(x=>x.leadIndex===(workspace.staffLead??0)).id;go('Project detail');};const inv=$('#exportInventory');if(inv)inv.onclick=()=>{const csv=v=>`"${String(v??'').replace(/"/g,'""').replace(/^[=+@-]/,"'$&")}"`;const data=[['Category','Item','Specification','Quantity','Unit','Supplier','Order reference','Status'],...workspace.inventory.filter(x=>x.projectId===context().projectId).map(x=>[x.category,x.name,x.spec,x.qty,x.unit,x.supplier,x.orderReference,x.status])];downloadText(`${context().projectId}-ordering-draft.csv`,data.map(row=>row.map(csv).join(',')).join('\r\n'),'text/csv');};const a=$('#exportAgreement');if(a)a.onclick=()=>{const c=context(),v=workspace.agreements.find(x=>x.projectId===c.projectId);if(!v)return toast('Save the project particulars first');downloadText(`${c.projectId}-supply-particulars-DRAFT.txt`,`UNREVIEWED DRAFT — NOT FOR EXECUTION\nProject: ${c.project.name} (${c.projectId})\nCustomer: ${v.customer}\nSite: ${v.site}\nPrice NZD excl GST: ${v.price||'Unspecified'}\nPayments:\n${v.payments}\nDelivery / terms / exclusions:\n${v.terms}\nReview notes:\n${v.review}\n\nAttach approved drawings, scope and reconciled kitset schedule. Confirm applicable statutory protections, payment requirements, signatures and legal review before execution. No signature is generated.`);};}
function roadmap(){return heading('Three workspaces. One shared journey.','SHP 1.3 connects the role concepts; operational services are the next phase.')+`<div class="roadmap"><section class="card"><span class="tag">SHP 1.3 · Available to review</span><h2 style="margin-top:18px">Connected role workflows</h2><ul><li>Lead pricing, notes and contract-ready projects</li><li>Categorized kitset ordering and shared documents</li><li>Inspections, variation assessment and approval</li><li>Tender scope, estimates, claims and task meters</li><li>Business profiles and completion preparation</li><li>Supplier priorities, upgrades and freight handovers</li><li>Delivery evidence, incident holds and invoice preferences</li><li>Development pricing workbook and validated CSV import</li><li>Compiled BOM uploads and physical inventory checks</li><li>Lockup and fitout test packages with trade shortlists</li></ul></section><section class="card"><span class="tag amber">Next · Operational foundation</span><h2 style="margin-top:18px">Verified accounts & records</h2><ul><li>Invitation-based sign-in and server permissions</li><li>Project-specific access and private contractor costs</li><li>Durable database, central evidence storage and version history</li><li>Lawyer-reviewed agreements and prescribed forms</li><li>Verified contractor licences and insurance</li></ul></section><section class="card"><span class="tag amber">Next · Connected services</span><h2 style="margin-top:18px">Integrations & delivery</h2><ul><li>Objective Build access/API verification</li><li>Authorised email note import</li><li>In-app audit trail, email and opt-in urgent SMS</li><li>Payments, memberships and cancellation handling</li><li>Nationwide builder records and tender matching</li><li>HHT carrier feed — access assumed, connection pending</li></ul></section></div><section class="card workspace-activity"><h2>Trial marketplace fees</h2><p>Contractor: ${money(workspace.fees.contractorMonthly||0)} / month excluding GST. Customer optional tender service: ${money(workspace.fees.customerTender||0)} per kitset project excluding GST. These are configurable proposals; billing is inactive.</p><p>Inspection schedules must come from actual consent conditions. Kitset quantities must come from approved engineering. Each LBP’s Record of Work is provided on completion independently of payment.</p><p class="small">All changes currently persist in this browser. Role previews illustrate access boundaries and do not enforce technical confidentiality.</p></section>`;}
function render(){const groups=menuGroups(),menus=groups.flatMap(x=>x[1]);if(!menus.includes(page)&&page!=='Project detail')page='Overview';const c=context();if(page==='Project detail')selected=projects.findIndex(x=>x.id===c.projectId);const mod=moduleFor(page);let content=page==='Overview'?overview():page==='Projects'?heading('Every project. One connected journey.','Confirmed projects from Shed House contract through the full customer build.')+`<section class="card">${table()}</section>`:page==='Project detail'?projectPage():page==='Sales & CRM'?crm():page==='Tender marketplace'?marketplace():page==='Sales & marketing'?marketing():page==='Project coordination'?coordinationPage():mod?mod.render(page,c):page==='Notifications'?notificationPage():roadmap();
content += staffFollowthrough();
content = inventoryReadinessPanel(c) + content;
content += projectBOMFilesPanel(c);
content += tenderPackagePanel(c);
if(page==='Inventory issues'&&role==='staff')content += unlinkedInventoryIncidents(c);
if(role==='contractor'&&page==='Pricing model')content+=`<section class="card workspace-activity"><h2>Development spreadsheet foundation</h2><p>Three fictional example rows demonstrate cost, markup and GST. This workbook is under development. Export its seven-column Import sheet as UTF-8 CSV, validate it above, then explicitly import the rows.</p><div class="quick-links"><a class="secondary" href="downloads/shp-contractor-pricing-development.xlsx" download>Download draft pricing workbook</a><a class="secondary" href="downloads/shp-contractor-pricing-development.csv" download>Download matching CSV examples</a></div><p class="small">The workbook initially calculates its three sample rows; extend formulas when adding rows. Formula and cached-total checks passed; visual workbook verification was unavailable. Review it in Excel before use. Imported prices and actual workbooks do not synchronise automatically.</p></section>`;
$('#app').innerHTML=`<aside><img class="logo" src="assets/logo-white.svg" alt="Shed House"><div class="eyebrow">${names[role]} / SHP 1.3</div><nav>${groups.map(([g,items])=>`<span class="nav-label">${g}</span>${items.map(m=>`<button data-go="${m}" class="${page===m||(page==='Project detail'&&m==='Projects')?'active':''}">${m}${m==='Notifications'&&unreadNotifications()?` <span class="count">${unreadNotifications()}</span>`:''}</button>`).join('')}`).join('')}</nav><div class="aside-bottom"><span class="tag amber">SHP 1.3 · ROLE PREVIEW</span><p>Connected from lead to handover.</p><button class="link" style="color:white" id="signout">← Role selection</button></div></aside><div class="shell"><div class="demo-strip">Private concept · Fictional project data · Changes save only in this browser · Billing, email and secure role accounts are not connected</div><header><span class="small">Shed House / ${names[role]}</span><input id="search" aria-label="Search projects or leads" placeholder="Search projects or leads…" value="${escape(filter)}"><div class="workspace-actions"><button class="secondary" id="inbox">Inbox${unreadNotifications()?` <span class="count">${unreadNotifications()}</span>`:''}</button><select id="role" aria-label="Preview role">${Object.keys(names).map(r=>`<option value="${r}" ${r===role?'selected':''}>${names[r]} preview</option>`).join('')}</select></div></header><main><div class="workspace-context"><label>Active project<select id="workspace-project">${permittedProjects().map(p=>`<option value="${p.id}" ${p.id===c.projectId?'selected':''}>${p.name}</option>`).join('')}</select></label><span class="context-info">${escape(c.project.id)} · ${escape(c.project.place)}<br>${role==='staff'?'Manage contracted supply and project coordination.':role==='customer'?'Your documents, inspections and tender decisions.':'Awarded project delivery and business tools.'}</span></div>${holdNotice(c.projectId)}${freightHoldNotice(c.projectId)}${content}<footer>SHP 1.3 · THREE CONNECTED WORKSPACES · Browser demonstration · Fees are proposals; no payments are taken</footer></main></div>`;
document.querySelectorAll('[data-go]').forEach(b=>b.onclick=()=>go(b.dataset.go));document.querySelectorAll('[data-project]').forEach(b=>b.onclick=()=>{selected=Number(b.dataset.project);workspace[role==='staff'?'staffProjectId':role==='customer'?'customerProjectId':'contractorProjectId']=projects[selected].id;saveWorkspace();go('Project detail');});$('#workspace-project').onchange=e=>{workspace[role==='staff'?'staffProjectId':role==='customer'?'customerProjectId':'contractorProjectId']=e.target.value;saveWorkspace();render();};$('#role').onchange=e=>{role=e.target.value;go('Overview');};$('#inbox').onclick=()=>go('Notifications');$('#signout').onclick=login;$('#search').onchange=e=>{filter=e.target.value.toLowerCase();if(!['Overview','Projects','Sales & CRM'].includes(page))page='Projects';render();};document.querySelectorAll('[data-tender]').forEach(b=>b.onclick=()=>tenderDetail(Number(b.dataset.tender)));if($('#addLead'))$('#addLead').onclick=addLead;if($('#capture'))$('#capture').onclick=addLead;document.querySelectorAll('[data-lead]').forEach(s=>s.onchange=()=>{leads[Number(s.dataset.lead)].stage=s.value;saveWorkspace();toast('Demo lead stage updated');});if(mod)mod.bind(page,c);bindShared();bindFollowthrough();bindV13(c);bindInventoryLinker(c);}
function v12MenuGroups(){const g=baseMenuGroups();if(role==='staff')g.splice(2,0,['Suppliers & logistics',['Suppliers & upgrades','Freight hub','Supply chain','Freight incidents']]);if(role==='customer')g.splice(1,0,['Kitset delivery',['Deliveries & evidence','Damage & missing items','Kitset upgrades']]);if(role==='contractor'){g[0][1].push('Invoice preferences');g[1][1].splice(4,0,'Pricing model','Delivery coordination');}return g;}
function v12ModuleFor(p){const logistics=role==='staff'?window.SHLogistics:role==='customer'?window.SHDeliveries:null;if(logistics?.pages.includes(p))return logistics;if(role==='contractor'&&p==='Delivery coordination')return {render:deliveryCoordination,bind:()=>{}};return baseModuleFor(p);}
function freightHoldNotice(projectId){const incidents=workspace.freightIncidents.filter(x=>x.projectId===projectId&&x.hold!==false&&x.status!=='Resolved');const held=workspace.shipments.filter(x=>x.projectId===projectId&&x.status==='On hold');if(!incidents.length&&!held.length)return '';return `<div class="hold-banner"><strong>Kitset delivery hold · Assessment required</strong><span>${incidents.length} unresolved freight issue${incidents.length===1?'':'s'} · ${held.length} held consignment${held.length===1?'':'s'}. Keep affected materials identifiable; do not install unsafe or disputed components until Shed House confirms the next step.</span> <button class="link" data-go="${role==='staff'?'Freight incidents':role==='customer'?'Damage & missing items':'Delivery coordination'}">Review delivery issues →</button></div>`;}
function deliveryCoordination(page,c){const own=k=>workspace[k].filter(x=>x.projectId===c.projectId);return heading('Deliveries ready for the build.','Read the manifest, delivery condition and Shed House’s incident assessment before installation.')+`<section class="card"><h2>Consignment overview</h2>${own('shipments').map(x=>`<article class="activity"><div><h3>${escape(x.carrier)} · ${escape(x.trackingNumber)}</h3><span class="tag amber">${escape(x.status)}</span><p>${escape(x.origin)} → ${escape(x.destination)} · ${escape(x.expectedDate)}</p><p class="small">Portal events are manual. The actual carrier source is separate.</p><div class="table-wrap"><table><thead><tr><th>Manifest component</th><th>Quantity</th></tr></thead><tbody>${(x.manifest||[]).map(m=>`<tr><td>${escape(m.item)}</td><td>${escape(m.qty)} ${escape(m.unit)}</td></tr>`).join('')}</tbody></table></div></div></article>`).join('')||'<p>No project consignments registered.</p>'}</section><section class="card workspace-activity"><h2>Freight issues and next steps</h2>${own('freightIncidents').map(x=>`<article class="customer-item"><h3>${escape(x.type)} · ${escape(x.item)}</h3><span class="tag ${x.status==='Resolved'?'':'amber'}">${escape(x.status)}</span><p>${escape(x.description)}</p><p>Owner: ${escape(x.owner||'Shed House to assign')} · Case: ${escape(x.caseReference||'Not supplied')}</p><p>Decision: ${escape(x.decision||'Awaiting assessment')}</p><p class="small">${x.hold!==false&&x.status!=='Resolved'?'Affected materials remain on hold.':'Coordinate the recorded next step with Shed House.'}</p></article>`).join('')||'<p>No delivery issues recorded.</p>'}</section>`;}
workspace.carrierDefaults||={name:'Hilton Haulage Transport',source:'User supplied 15 October 2026',website:'https://hiltonhaulage.co.nz/',trackingPortalUrl:'',liveStatus:'Not connected — confirm account portal/API with Hilton Haulage'};
function menuGroups(){const groups=v12MenuGroups();if(role==='staff'){groups[1][1].splice(2,0,'BOM documents','Inventory issues');groups[groups.length-1][1].splice(1,0,'TMP packages','Trade directory','Membership tiers');}if(role==='customer'){groups[0][1].push('Inventory receipt check');groups[groups.length-1][1].splice(1,0,'TMP packages');}if(role==='contractor'){groups[0][1].push('Membership tiers');groups[1][1].push('TMP packages');}return groups;}
function moduleFor(p){if(role==='staff'&&window.SHBOMTender.pages.includes(p))return window.SHBOMTender;if(role==='customer'&&window.SHInventoryChecks.pages.includes(p))return window.SHInventoryChecks;if((role==='staff'||role==='contractor')&&window.SHMembership.pages.includes(p))return window.SHMembership;if(p==='Inventory issues'&&role==='staff')return {render:inventoryIssuesPage,bind:()=>{}};if(p==='TMP packages')return {render:readOnlyTMPPackage,bind:()=>{}};return v12ModuleFor(p);}
function inventoryReadinessPanel(c){if(page!=='Kitset inventory')return '';const s=window.SHInventoryChecks.summary(c.projectId,workspace);return `<section class="card inventory-readiness"><div class="card-top"><h2>Delivery check against supplied inventory</h2><button class="secondary" data-go="${role==='staff'?'Inventory issues':'Inventory receipt check'}">${role==='staff'?'Review inventory issues':'Check each supplied component'}</button></div><p>The receiving customer must thoroughly check quantities, condition, labels and delivery paperwork. Uploaded photos alone do not confirm every component. Rows with a damage or shortage report remain flagged until the issue is assessed.</p><div class="quick-links"><span class="tag grey">${s.total} rows</span><span class="tag amber">${s.unchecked} not checked</span><span class="tag amber">${s.damaged} damaged</span><span class="tag amber">${s.missing} missing</span><span class="tag">${s.complete} checked complete</span>${role==='staff'?'<button class="link" data-go="BOM documents">Upload / reconcile compiled BOM →</button>':''}</div></section>`;}
function inventoryIssuesPage(page,c){const items=workspace.inventory.filter(i=>i.projectId===c.projectId);return heading('Identify every damaged or missing component.','Physical check results and outstanding incidents stay linked to the supplied inventory line.')+`<section class="card"><div class="table-wrap"><table><thead><tr><th>Component / specification</th><th>Expected</th><th>Received</th><th>Damaged</th><th>Check / incident</th></tr></thead><tbody>${items.map(i=>{const r=window.SHInventoryChecks.rowState(i,workspace);return `<tr class="${r.damaged||r.missing?'inventory-alert-row':''}"><td><strong>${escape(i.name)}</strong>${escape(i.spec||'Specification pending')}<p class="small">${escape(i.itemCode||'')} · ${escape(i.sourceBOMVersion||'No linked BOM revision')}</p></td><td>${escape(i.qty)} ${escape(i.unit)}</td><td>${r.receivedQty==null?'Not checked':escape(r.receivedQty)}</td><td>${r.damagedQty==null?'Not checked':escape(r.damagedQty)}</td><td><span class="tag ${r.complete?'':'amber'}">${escape(r.status)}</span>${r.incidents.map(x=>`<p class="small">${escape(x.type)} · ${escape(x.status)} · ${escape(x.caseReference||x.id)}</p>`).join('')}</td></tr>`;}).join('')||'<tr><td colspan="5">No supplied inventory yet. Upload and reconcile a BOM first.</td></tr>'}</tbody></table></div><p class="small">Counts are recorded by the receiving customer. SH assesses issues separately; a later check does not resolve an earlier incident automatically.</p><button class="secondary" data-go="Freight incidents">Review freight assessment →</button></section>`;}
function projectBOMFilesPanel(c){if(!['Kitset inventory','Project documents','Approved documents','Scope package'].includes(page))return '';const records=workspace.bomDocuments.filter(d=>d.projectId===c.projectId);if(!records.length)return '';return `<section class="card workspace-activity"><h2>Compiled BOM files for this project</h2>${records.map(d=>`<article class="activity"><div><h3>${escape(d.name)}</h3><p>Version ${escape(d.version)} · ${escape(d.status)} · ${escape(d.attachment.name)}</p><button class="secondary" data-project-bom="${escape(d.id)}">Download locally stored PDF</button></div></article>`).join('')}<p class="small">Actual files remain on this device. Check the version and SH review status before using quantities for supply or installation.</p></section>`;}
function readOnlyTMPPackage(page,c){const p=workspace.tenderPackages.find(x=>x.projectId===c.projectId);return heading('A clear package for every tender.','Review the intended work, trade interfaces and milestones before pricing.')+(p?`<section class="card"><span class="tag amber">${escape(p.status)} · DEMONSTRATION</span><h2 style="margin-top:16px">${escape(p.title)}</h2><p>${escape(p.scope)}</p><h3>Inclusions</h3><p>${escape(p.inclusions)}</p><h3>Exclusions</h3><p>${escape(p.exclusions)}</p><h3>Site, consent and inspections</h3><p>${escape(p.siteRequirements)}</p><p>${escape(p.consentReferences)}</p><p>${escape(p.inspectionRequirements)}</p><h3>Milestones</h3><ol>${p.milestones.map(x=>`<li>${escape(x)}</li>`).join('')}</ol><h3>Trade / supply price packages</h3>${p.tradePricingScopes.map(x=>`<article class="activity"><div><h3>${escape(x.trade)}</h3><p>${escape(x.scope)}</p><p class="small">Included: ${escape(x.inclusions)}<br>Excluded: ${escape(x.exclusions)}</p></div></article>`).join('')}</section>`:'<section class="card"><p>Select “TMP Demo · Lockup shell” or “TMP Demo · Internal fitout” in Active project to review a test package.</p></section>');}
function tenderPackagePanel(c){if(page==='TMP membership')return `<section class="card"><h2>Review proposed role-based memberships</h2><p>Builder, trade and supply-only pricing proposals are separate from the existing NZ$99 monthly trial configuration.</p><button class="secondary" data-go="Membership tiers">Compare proposed rates →</button></section>`;if(page!=='Tender marketplace')return '';return `<section class="card workspace-activity"><h2>Two TMP test projects</h2><p>Draft test packages illustrate the split between lockup shell and internal fitout. They do not issue real invitations or assert consent approval.</p>${workspace.tenderPackages.map(p=>`<article class="activity"><div><span class="tag amber">DEMO · ${escape(p.status)}</span><h3>${escape(p.title)}</h3><p>${escape(p.region)} · ${escape(p.scope)}</p><button class="secondary" data-open-package="${escape(p.projectId)}">Open trade scopes →</button></div></article>`).join('')}</section>`;}
function bindV13(c){document.querySelectorAll('[data-open-package]').forEach(b=>b.onclick=()=>{workspace[role==='staff'?'staffProjectId':role==='customer'?'customerProjectId':'contractorProjectId']=b.dataset.openPackage;saveWorkspace();go('TMP packages');});document.querySelectorAll('[data-project-bom]').forEach(b=>b.onclick=async()=>{try{const d=workspace.bomDocuments.find(x=>x.id===b.dataset.projectBom&&x.projectId===c.projectId);if(!d)return;const file=await c.files.get(d.attachment.id);if(!file?.blob||file.ownerId!==d.id)return toast('This PDF is unavailable on this device.');const url=URL.createObjectURL(file.blob),a=document.createElement('a');a.href=url;a.download=file.name;a.click();setTimeout(()=>URL.revokeObjectURL(url),1000);}catch{toast('Unable to read the locally stored PDF.');}});document.querySelectorAll('[data-inventory-row]').forEach(row=>{const item=workspace.inventory.find(x=>x.id===row.dataset.inventoryRow&&x.projectId===c.projectId);if(!item)return;const r=window.SHInventoryChecks.rowState(item,workspace),cell=row.querySelector('td');if(!cell)return;const note=document.createElement('div');note.className='inventory-state';const badge=document.createElement('span');badge.className='tag '+(r.complete?'':'amber');badge.textContent=r.status;note.append(badge);if(r.damaged||r.missing||r.incidents.length){row.classList.add('inventory-alert-row');const text=document.createElement('span');text.className='small';text.textContent=` Received ${r.receivedQty??'not checked'}; damaged ${r.damagedQty??'not checked'} · ${r.incidents.length} unresolved incident(s)`;note.append(text);}cell.append(note);});}
window.SHBOMTender.seedTestProjects({...context(),projects},{model:'Gable 120',region:'Waikato'});
function unlinkedInventoryIncidents(c){const items=workspace.inventory.filter(x=>x.projectId===c.projectId),records=workspace.freightIncidents.filter(x=>x.projectId===c.projectId&&!['resolved','closed'].includes(String(x.status).toLowerCase())&&!items.some(i=>i.id===x.inventoryId));if(!records.length)return '';return `<section class="card workspace-activity"><h2>Reports needing an exact inventory link</h2><p>Repeated manufacturer codes and different cut lengths must be matched to the correct supplied line. Review the report before linking it; names and codes alone are not used to guess the component.</p>${records.map(r=>`<form class="inventory-link-form" data-link-incident="${escape(r.id)}"><h3>${escape(r.type)} · ${escape(r.item)}</h3><p>${escape(r.description)}</p><label>Exact supplied inventory line<select name="inventoryId" required><option value="">Choose after reviewing the report</option>${items.map(i=>`<option value="${escape(i.id)}">${escape(i.name)} · ${escape(i.spec||'Specification pending')} · ${escape(i.itemCode||i.id)}</option>`).join('')}</select></label><button class="secondary">Link report to inventory line</button></form>`).join('')}</section>`;}
function bindInventoryLinker(c){document.querySelectorAll('[data-link-incident]').forEach(f=>f.onsubmit=e=>{e.preventDefault();const d=Object.fromEntries(new FormData(f)),incident=workspace.freightIncidents.find(x=>x.id===f.dataset.linkIncident&&x.projectId===c.projectId),item=workspace.inventory.find(x=>x.id===d.inventoryId&&x.projectId===c.projectId);if(!incident||!item)return;incident.previousInventoryId=incident.inventoryId||null;incident.inventoryId=item.id;incident.itemCode=item.itemCode||'';incident.sourceBOMId=item.sourceBOMId||null;incident.history||=[];incident.history.push({at:new Date().toISOString(),by:'staff',status:incident.status,note:'SH linked report to exact supplied inventory line: '+item.id});notifyProject({title:'Inventory report linked to supplied component',message:`${incident.type}: ${item.name}. Assessment status remains ${incident.status}.`,projectId:c.projectId,roles:['staff','customer','contractor'],kind:'freight-incident'});saveWorkspace();render();});}
for(const p of workspace.tenderPackages){if(!workspace.tenderScopes.some(x=>x.projectId===p.projectId))workspace.tenderScopes.push({id:p.id+'-scope',projectId:p.projectId,title:p.title,inclusions:p.inclusions,exclusions:p.exclusions,responsibilities:p.scope,siteAccess:p.siteRequirements,consentReferences:p.consentReferences,specification:'Demonstration — approved drawings and BOM required',acceptance:p.milestones.join('; '),version:1,status:'Draft demonstration'});}
saveWorkspace();
